/* shmget_example.c: Demonstrates creating a System V shared memory segment. */
#include <stdio.h>
#include <stdlib.h>
#include <sys/shm.h>
#include <sys/stat.h>
#include <errno.h>

#define SHM_SIZE 4096 // 4 KB
#define SHM_KEY 9876  // A fixed key for demonstration

int main() {
    int shmid;
    // Flags: IPC_CREAT creates if necessary, S_IRUSR|S_IWUSR defines read/write permissions for the owner.
    int shm_flags = IPC_CREAT | S_IRUSR | S_IWUSR;

    printf("Attempting to allocate shared memory segment with key %d and size %d bytes...\n", SHM_KEY, SHM_SIZE);

    // 1. Create the shared memory segment
    shmid = shmget(SHM_KEY, SHM_SIZE, shm_flags);

    if (shmid == -1) {
        perror("shmget failed");

        if (errno == EEXIST) {
            fprintf(stderr, "Error: Segment already exists. Try using IPC_EXCL or cleaning up the existing segment.\n");
        }
        return EXIT_FAILURE;
    }

    printf("Successfully obtained shared memory segment ID: %d\n", shmid);
    printf("To use it, another process must attach via shmat().\n");

    // 2. Clean up the segment immediately for demonstration purposes (usually done by a controlling process)
    if (shmctl(shmid, IPC_RMID, NULL) == -1) {
        perror("shmctl (IPC_RMID) failed");
    } else {
        printf("Segment removed.\n");
    }

    return EXIT_SUCCESS;
}
